{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Accessible label for the file input.",
      "required": true
    },
    {
      "name": "value",
      "type": "File | File[] | null",
      "description": "Currently selected file(s). Controlled component.",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(files: File | File[] | null) => void",
      "description": "Callback fired when files are selected or removed.",
      "required": true
    },
    {
      "name": "changeAction",
      "type": "(files: File | File[] | null) => Promise<void>",
      "description": "Async change action (React 19 transitions pattern). Use for immediate upload on file selection."
    },
    {
      "name": "accept",
      "type": "string",
      "description": "Accepted file types. Uses the HTML accept attribute format (e.g. \"image/*\", \".pdf,.doc\")."
    },
    {
      "name": "isMultiple",
      "type": "boolean",
      "description": "Whether multiple files can be selected. When true, value and onChange use File[] instead of File.",
      "default": "false"
    },
    {
      "name": "maxSize",
      "type": "number",
      "description": "Maximum file size in bytes. Files exceeding this are rejected with an error status."
    },
    {
      "name": "maxFiles",
      "type": "number",
      "description": "Maximum number of files (only applies when isMultiple is true)."
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Visually hides the label while keeping it accessible to screen readers.",
      "default": "false"
    },
    {
      "name": "description",
      "type": "string",
      "description": "Description text displayed between the label and input."
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Displays an \"Optional\" indicator next to the label. Mutually exclusive with isRequired.",
      "default": "false"
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Displays a \"Required\" indicator next to the label and adds a screen-reader-only \"Required\" description to the trigger (assistive tech does not reliably announce aria-required on the trigger). Mutually exclusive with isOptional.",
      "default": "false"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disables the input, preventing interaction and dimming the element.",
      "default": "false"
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the input is disabled. With isDisabled, shows a tooltip on hover/keyboard focus and keeps the trigger focusable via aria-disabled (opening the file picker stays blocked). Use this instead of wrapping a disabled FileInput in Tooltip; disabled controls swallow the hover events an external Tooltip needs."
    },
    {
      "name": "isLoading",
      "type": "boolean",
      "description": "Puts the input in a loading state, showing a spinner and setting aria-busy.",
      "default": "false"
    },
    {
      "name": "placeholder",
      "type": "string",
      "description": "Placeholder text shown when no file is selected.",
      "default": "\"Choose file\" or \"Choose files\""
    },
    {
      "name": "mode",
      "type": "'input' | 'dropzone'",
      "description": "Visual mode. 'input' is a compact inline style; 'dropzone' is a larger area with drag-and-drop support.",
      "default": "'input'"
    },
    {
      "name": "status",
      "type": "{type: 'error' | 'warning' | 'success', message?: string}",
      "description": "Validation status: applies a colored border. If message is provided, displays a floating message below the input. Error type also sets aria-invalid."
    },
    {
      "name": "statusVariant",
      "type": "'attached' | 'detached' | 'tooltip'",
      "description": "How the status message is placed relative to the input. attached overlaps directly below the input (bordered treatment); detached floats below as a separate element with spacing; tooltip hides the message box and surfaces it in a tooltip on the status icon. Dropzone mode does not support attached: use detached or tooltip. From the next minor release, a dropzone resolves attached to detached and defaults to it.",
      "default": "'attached'"
    },
    {
      "name": "labelTooltip",
      "type": "string",
      "description": "Tooltip text displayed in an info icon at the end of the label."
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned."
    },
    {
      "name": "containerXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the field container (label, control, and status together). No effect inside InputGroup (style the InputGroup instead) or in a `horizontal-labels` FormLayout. Root `xstyle`, `className`, and `style` are not accepted."
    },
    {
      "name": "containerClassName",
      "type": "string",
      "description": "Class name for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "containerStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the visual control box: the element that paints the border and background and holds icons and end controls. Never the native input."
    },
    {
      "name": "controlClassName",
      "type": "string",
      "description": "Class name for the visual control box."
    },
    {
      "name": "controlStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the visual control box."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
